## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/epiduralSteroidLogic.ts`

```typescript
export type SpineRegion = "lumbar" | "cervical" | "thoracic";
export type ApproachType = "interlaminar" | "transforaminal" | "caudal";

export type EpiduralSteroidInput = {
  age: string; spineRegion: string; approachType: string;
  symptomDurationWeeks: string; painScore: string; symptoms: string[];
  conservativeTherapyWeeks: string; conservativeTherapies: string[];
  imagingFindings: string[];
  activeInfection: boolean; coagulopathy: boolean; allergy: boolean;
  priorInjectionResponse: string; priorInjectionCount: string;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessEpiduralSteroid(input: EpiduralSteroidInput) {
  const conservWeeks = parseFloat(input.conservativeTherapyWeeks) || 0;
  const painScore = parseFloat(input.painScore) || 0;
  const priorCount = parseInt(input.priorInjectionCount) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active infection — absolute contraindication");
  if (input.coagulopathy) contraindications.push("Uncorrected coagulopathy — hold anticoagulation per guidelines before proceeding");
  if (input.allergy) contraindications.push("Allergy to steroids or contrast — use alternative agents or consider desensitization");

  if (contraindications.length > 0) {
    return { recommendation: "ESI Contraindicated", cor: "III" as COR, loe: "C", urgency: "Contraindicated", rationale: ["Contraindications identified — address before proceeding."], contraindications, optimizationSteps: ["Bridge anticoagulation per procedural guidelines", "Allergy evaluation if steroid/contrast allergy"] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  const hasRadicular = input.symptoms.includes("radicular-pain");
  const hasNeurogenicClaudication = input.symptoms.includes("neurogenic-claudication");
  const hasDiscHerniation = input.imagingFindings.includes("disc-herniation");
  const hasStenosis = input.imagingFindings.includes("central-stenosis") || input.imagingFindings.includes("foraminal-stenosis");

  if (priorCount >= 3) {
    cor = "IIb"; urgency = "Frequency Limit Reached";
    rationale.push("Most payers limit ESI to 3 injections per region per year");
    rationale.push("Consider alternative interventions: RFA, surgery, or pain psychology");
    optimizationSteps.push("Evaluate for surgical candidacy if not already done");
    optimizationSteps.push("Consider radiofrequency ablation for facetogenic component");
  } else if (hasRadicular && hasDiscHerniation && conservWeeks >= 4) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Radicular pain with imaging-confirmed disc herniation and nerve root compression");
    rationale.push("Conservative therapy trial completed (≥4 weeks)");
    rationale.push("ESI provides short-term pain relief and may facilitate PT participation");
  } else if ((hasNeurogenicClaudication || hasRadicular) && hasStenosis && conservWeeks >= 4) {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Neurogenic claudication or radiculopathy with stenosis");
    rationale.push("ESI is reasonable for short-term symptom relief");
  } else if (conservWeeks < 4) {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("Conservative therapy trial insufficient — continue for ≥4 weeks");
    optimizationSteps.push("Continue PT, NSAIDs, and activity modification for ≥4 weeks");
  } else {
    cor = "IIb"; urgency = "Insufficient Criteria";
    rationale.push("Radicular symptoms or imaging correlation not clearly documented");
    optimizationSteps.push("Obtain MRI to confirm nerve root compression");
    optimizationSteps.push("Document dermatomal distribution of symptoms");
  }

  if (input.priorInjectionResponse === "good") rationale.push("Prior ESI response was good — repeat injection is appropriate");
  if (input.priorInjectionResponse === "none") optimizationSteps.push("Prior ESI had no response — reconsider diagnosis and approach; consider transforaminal vs. interlaminar");
  if (painScore >= 8) rationale.push("Severe pain (NRS ≥8) supports intervention to facilitate PT participation");

  return { recommendation: cor === "I" ? "ESI Recommended" : cor === "IIa" ? "ESI Reasonable" : urgency === "Frequency Limit Reached" ? "Frequency Limit — Consider Alternatives" : "Continue Conservative Therapy", cor, loe: hasDiscHerniation ? "A" : "B", urgency, rationale, contraindications, optimizationSteps };
}
